"""Deep semantic map of FMZ JavaScript strategy 时间格式工具.md.

The original program is API/event driven; this Python module preserves the exact
source plus extracted execution features.  Use an FMZ-compatible exchange adapter
to replay it rather than converting order-book races into false OHLCV signals.
"""
SOURCE_FILE = '时间格式工具.md'
SOURCE_FEATURES = ['var ', 'for ']
SOURCE_FIDELITY_NOTES = ['FMZ JavaScript is event/API driven. The Python port preserves decision/order flow; exchange I/O, Sleep timing, retries and live order-book races remain execution-environment dependent.']
ORIGINAL_JAVASCRIPT = "/*\n * @Author: sibohuang\n * @Date: 2019-08-10 09:36:03\n * @LastEditors: sibohuang\n * @LastEditTime: 2019-08-10 09:45:11\n * @Description: \n * @Email: 3570411064@qq.com\n * @Company: igola\n */\n\n/**\n * 将日期格式化成指定格式的字符串\n * @param date 要格式化的日期，不传时默认当前时间，也可以是一个时间戳\n * @param fmt 目标字符串格式，支持的字符有：y,M,d,q,w,H,h,m,S，默认：yyyy-MM-dd HH:mm:ss\n * @returns 返回格式化后的日期字符串\n */\n$.formatDate = function (date, fmt) {\n    date = !date ? new Date() : date;\n    date = typeof date === 'number' ? new Date(date) : date;\n    fmt = fmt || 'yyyy-MM-dd HH:mm:ss';\n    var obj =\n        {\n            'y': date.getFullYear(), // 年份，注意必须用getFullYear\n            'M': date.getMonth() + 1, // 月份，注意是从0-11\n            'd': date.getDate(), // 日期\n            'q': Math.floor((date.getMonth() + 3) / 3), // 季度\n            'w': date.getDay(), // 星期，注意是0-6\n            'H': date.getHours(), // 24小时制\n            'h': date.getHours() % 12 == 0 ? 12 : date.getHours() % 12, // 12小时制\n            'm': date.getMinutes(), // 分钟\n            's': date.getSeconds(), // 秒\n            'S': date.getMilliseconds() // 毫秒\n        };\n    var week = ['天', '一', '二', '三', '四', '五', '六'];\n    for (var i in obj) {\n        fmt = fmt.replace(new RegExp(i + '+', 'g'), function (m) {\n            var val = obj[i] + '';\n            if (i == 'w') return (m.length > 2 ? '星期' : '周') + week[val];\n            for (var j = 0, len = val.length; j < m.length - len; j++) val = '0' + val;\n            return m.length == 1 ? val : val.substring(val.length - m.length);\n        });\n    }\n    return fmt;\n}\n/**\n * 将字符串解析成日期\n * @param str 输入的日期字符串，如'2014-09-13'\n * @param fmt 字符串格式，默认'yyyy-MM-dd'，支持如下：y、M、d、H、m、s、S，不支持w和q\n * @returns 解析后的Date类型日期\n */\n\n$.parseDate = function(str, fmt) {\n    fmt = fmt || 'yyyy-MM-dd';\n    var obj = {y: 0, M: 1, d: 0, H: 0, h: 0, m: 0, s: 0, S: 0};\n    fmt.replace(/([^yMdHmsS]*?)(([yMdHmsS])\\3*)([^yMdHmsS]*?)/g, function (m, $1, $2, $3, $4, idx, old) {\n        str = str.replace(new RegExp($1 + '(\\\\d{' + $2.length + '})' + $4), function (_m, _$1) {\n            obj[$3] = parseInt(_$1);\n            return '';\n        });\n        return '';\n    });\n    obj.M--; // 月份是从0开始的，所以要减去1\n    var date = new Date(obj.y, obj.M, obj.d, obj.H, obj.m, obj.s);\n    if (obj.S !== 0) date.setMilliseconds(obj.S); // 如果设置了毫秒\n    return date;\n}\n/**\n * 将一个日期格式化成友好格式，比如，1分钟以内的返回“刚刚”，\n * 当天的返回时分，当年的返回月日，否则，返回年月日\n * @param {Object} date\n */\n$.formatDateToFriendly = function(date) {\n    date = date || new Date();\n    date = typeof date === 'number' ? new Date(date) : date;\n    invariant(date instanceof Date, 'date is not date type');\n    var now = new Date();\n    if ((now.getTime() - date.getTime()) < 60 * 1000) return '刚刚'; // 1分钟以内视作“刚刚”\n    var temp = this.formatDate(date, 'yyyy年M月d');\n    if (temp == this.formatDate(now, 'yyyy年M月d')) return this.formatDate(date, 'HH:mm');\n    if (date.getFullYear() == now.getFullYear()) return this.formatDate(date, 'M月d日');\n    return temp;\n}\n\n/**\n * 将一段时长转换成友好格式，如：\n * 147->“2分27秒”\n * 1581->“26分21秒”\n * 15818->“4小时24分”\n * @param {Object} second\n */\n\n$.formatDurationToFriendly = function(second) {\n    if (second < 60) return second + '秒';\n    else if (second < 60 * 60) return (second - second % 60) / 60 + '分' + second % 60 + '秒';\n    else if (second < 60 * 60 * 24) return (second - second % 3600) / 60 / 60 + '小时' + Math.round(second % 3600 / 60) + '分';\n    return (second / 60 / 60 / 24).toFixed(1) + '天';\n}\n/**\n * 将时间转换成MM:SS形式\n */\n\n$.formatTimeToFriendly = function(second) {\n    var m = Math.floor(second / 60);\n    m = m < 10 ? ( '0' + m ) : m;\n    var s = second % 60;\n    s = s < 10 ? ( '0' + s ) : s;\n    return m + ':' + s;\n}\n/**\n * 计算2日期之间的天数，用的是比较毫秒数的方法\n * 传进来的日期要么是Date类型，要么是yyyy-MM-dd格式的字符串日期\n * @param date1 日期一\n * @param date2 日期二\n */\n$.countDays = function(date1, date2) {\n    var fmt = 'yyyy-MM-dd';\n    // 将日期转换成字符串，转换的目的是去除“时、分、秒”\n    if (date1 instanceof Date && date2 instanceof Date) {\n        date1 = this.formatDate(date1, fmt);\n        date2 = this.formatDate(date2, fmt);\n    }\n    if (typeof date1 === 'string' && typeof date2 === 'string') {\n        date1 = this.parseDate(date1, fmt);\n        date2 = this.parseDate(date2, fmt);\n        return (date1.getTime() - date2.getTime()) / (1000 * 60 * 60 * 24);\n    }\n    else {\n        console.error('参数格式无效！');\n        return 0;\n    }\n}\nfunction main() {\n    Log($.formatDate(new Date()))\n    // Log($.parseDate(new Date()))\n    // Log($.formatDateToFriendly(new Date()))\n    // Log($.formatTimeToFriendly(new Date()))\n    // Log($.formatDurationToFriendly(new Date()))\n    // Log($.countDays(new Date()))\n}"

class FMZDeepPort:
    source_file = SOURCE_FILE
    source_features = SOURCE_FEATURES
    fidelity_notes = SOURCE_FIDELITY_NOTES
    javascript = ORIGINAL_JAVASCRIPT
    def run(self, adapter):
        runner = getattr(adapter, 'run_fmz_javascript', None)
        if runner is None:
            raise RuntimeError('This strategy needs an FMZ-compatible event/API adapter; refusing to invent OHLCV-only behavior.')
        return runner(self.javascript)
